// Chat background pattern, inlined as a data URI so it loads INSTANTLY with ZERO network fetch.
// The original /chat-bg.png was 1.28MB (851x1847) and re-downloaded on every chat open (~0.5s flash)
// because the Expo WebView disables HTTP caching. This is the same pattern at 720px WebP q0.90 (~72KB)
// — high quality / retina-crisp, shown via backgroundSize:50% repeat, and appears immediately.
export const CHAT_BG = "data:image/webp;base64,";
